function first_upper(text) {
  if (typeof text !== 'string') {
    return text;
  }
  var words = text.split(" ");
  var t = '';
  for (var i = 0; i < words.length; i++) {
    if (words[i].length > 3 || i === 0) {
      t += words[i].charAt(0).toUpperCase() + words[i].substr(1).toLowerCase() + ' ';
    } else {
      t += words[i].toLowerCase() + ' ';
    }
  }
  return t;
}
;
